import React, { useEffect, useState } from "react";
import { Zap } from "lucide-react";

const WorkerSplash = ({ onComplete }) => {
  const [status, setStatus] = useState("BOOTING_OS");

  useEffect(() => {
    const sequence = ["SCANNING_ID", "SYNCING_NODE", "READY_OPERATOR"];
    sequence.forEach((text, i) => setTimeout(() => setStatus(text), (i + 1) * 800));
    setTimeout(onComplete, 3500);
  }, [onComplete]);

  return (
    <div className="h-screen bg-[#47510B] flex flex-col items-center justify-center font-mono">
      <div className="border-[10px] border-[#CAD23C] p-10 rounded-[45px] animate-bounce shadow-heavy bg-[#47510B]">
        <Zap size={80} className="text-[#CAD23C] fill-[#CAD23C]" />
      </div>
      <h1 className="mt-12 text-[#FFF24D] font-black italic text-5xl uppercase tracking-tighter text-center leading-none">
        Trash_2_Track<br/>
        <span className="text-white opacity-40 text-xl tracking-[0.3em] not-italic">WORKER_ELITE_v3</span>
      </h1>
      <div className="mt-10 w-56 h-2 bg-black/20 rounded-full overflow-hidden border border-white/10">
        <div className="h-full bg-[#FF5B03] animate-progress shadow-[0_0_15px_#FF5B03]" />
      </div>
      <p className="mt-4 text-[#CAD23C] font-black text-[10px] tracking-[0.5em] animate-pulse">{status}...</p>
    </div>
  );
};

export default WorkerSplash;
